const CACHE_NAME="berbagi-cerita-v1",urlsToCache=["/","/index.html","/images/logo.png","/images/leaf-green.png","/images/leaf-shadow.png","/images/marker-icon.png","/images/marker-icon-2x.png","/images/marker-shadow.png","/images/logo-192.png","/images/logo-512.png","/manifest.json"];self.addEventListener("install",(e=>{e.waitUntil(caches.open(CACHE_NAME).then((e=>e.addAll(urlsToCache)))),self.skipWaiting()})),self.addEventListener("activate",(e=>{e.waitUntil(clients.claim())})),self.addEventListener("message",(e=>{e.data&&"SKIP_WAITING"===e.data.type&&self.skipWaiting(),e.data?.title&&self.registration.showNotification(e.data.title,e.data.options||{})})),self.addEventListener("fetch",(e=>{e.respondWith(caches.match(e.request).then((t=>t||fetch(e.request))))})),self.addEventListener("push",(e=>{let t={title:"Notifikasi",options:{body:"Ada cerita baru!"}};if(e.data)try{t=e.data.json()}catch(e){}e.waitUntil(self.registration.showNotification(t.title,t.options))}));